local config = {
  ui_story_30760401_1_1_dialog_content = "Kau bohong saat bilang \"<color=#FFB400>Shadow akan menyelimuti tempat ini</color>\", Scam Artist?",
  ui_story_30760401_1_2_dialog_content = "Tentu saja, aku sengaja tidak mengatakannya secara langsung supaya semua jadi lebih menarik.",
  ui_story_30760401_1_3_dialog_content = "Kupikir begitu. Omong-omong, aku datang sesuai permintaanmu, jadi kalau ada yang mau kau katakan, katakanlah.",
  ui_story_30760401_1_4_dialog_content = "Baiklah, ayo pergi ke tempat yang sedikit lebih sepi.",
  ui_story_30760401_1_5_dialog_content = "Aku orang sederhana dengan tujuan yang sederhana pula. Aku bosan dan tidak ada yang bisa dilakukan di sini. Itulah perlunya kau.",
  ui_story_30760401_1_6_dialog_content = "Biasanya, aku hanya membuat masalah untukmu. Kali ini aku tidak mau begitu, jadi aku memanggilmu ke sini.",
  ui_story_30760401_1_7_dialog_content = "Aku mengerti. Kau ingin aku datang ke sini hanya untuk menghilangkan kebosananmu... Dan kalau aku menolak, kau akan mencari cara lain untuk membuat masalah?",
  ui_story_30760401_1_8_dialog_content = "Tepat.",
  ui_story_30760401_1_9_dialog_content = "Jadi, kenapa kau tiba-tiba sangat jujur tentang ini... Omong-omong, kalau ada sesuatu yang aku bisa bantu, jangan ragu untuk meminta.",
  ui_story_30760401_1_10_dialog_content = "Ayo main <color=#FFB400>tebak-tebakan</color> kecil dengan kemampuan psikismu, Navigator.",
  ui_story_30760401_1_11_dialog_content = "Aku tidak tahu kemampuanku bisa dipakai untuk bermain dan bersenang-senang... Apa yang harus kutebak?",
  ui_story_30760401_1_12_dialog_content = "Hmmm... Untuk ronde pertama, katakan kapan <color=#FFB400>burung</color> di balik pintu akan pergi?",
  ui_story_30760401_1_13_dialog_content = "Burung di balik pintu? Aku melihat seutas kain hijau. Itu <color=#FFB400>Dove</color>?",
  ui_story_30760401_1_14_option_content = "Menurutku burung itu akan pergi tak lama lagi.",
  ui_story_30760401_1_15_dialog_content = "Bagaimanapun, Dove biasanya cukup sibuk. Meskipun selalu mencoba bermalas-malasan, dia tidak akan bisa tinggal di sini terlalu lama.",
  ui_story_30760401_1_16_dialog_content = "<color=#e8d9bb>Setelah beberapa saat...</color>",
  ui_story_30760401_1_17_dialog_content = "Sepertinya burung itu tidak berencana pergi.",
  ui_story_30760401_1_18_dialog_content = "Nah, sebagai hukuman kecil, bagaimana kalau kau mengusirnya?",
  ui_story_30760401_1_19_option_content = "Menurutku burung itu tidak akan segera pergi.",
  ui_story_30760401_1_20_dialog_content = "Bagaimanapun, Dove suka bermalas-malasan.",
  ui_story_30760401_1_21_dialog_content = "Setelah beberapa saat...",
  ui_story_30760401_1_22_dialog_content = "Sepertinya burung itu tidak berencana pergi.",
  ui_story_30760401_1_23_dialog_content = "Sepertinya kau benar. Sebagai hukuman untukku, aku akan mengusir burung itu.",
  ui_story_30760401_1_24_dialog_content = "Kenapa tiba-tiba ada hukuman? Dan kenapa mengusir Dove?",
  ui_story_30760401_1_25_dialog_content = "Lihat, jubahnya bergetar. Dia jelas takut padamu!",
  ui_story_30760401_1_26_dialog_content = "Dia akan menghalangi orang yang ingin keluar masuk dari pintu, dan aku tidak ingin dia mendengar percakapan kita...",
  ui_story_30760401_1_27_dialog_content = "Tidak, kau tidak perlu. Aku akan...",
  ui_story_30760401_1_28_dialog_content = "Dove, jangan hiraukan dia!",
  ui_story_30760401_1_29_dialog_content = "Benarkah? Untuk keselamatanmu sendiri, gadis kecil, aku sarankan kau tidak menguping.",
  ui_story_30760401_1_30_dialog_content = "Aku tidak menguping, hanya bermalas-malasan. Tidak, maksudku beristirahat!",
  ui_story_30760401_1_A1_dialog_content = "Wah! Kau tidak adil padaku!",
  ui_story_30760401_1_31_dialog_content = "Itu sudah keterlaluan! Aku akan memenangkan permainan ini melawanmu untuk membalaskan Dove!",
  ui_story_30760401_1_32_dialog_content = "Baiklah, ayo lanjutkan. Prediksi keduamu... Apakah ruangan ini <color=#FFB400>bersih</color> atau <color=#FFB400>kotor</color>?",
  ui_story_30760401_1_33_dialog_content = "Tidak perlu ramalan untuk itu. Perlengkapan dukungan di Colossus selalu membersihkannya.",
  ui_story_30760401_1_34_dialog_content = "Apa mereka?",
  ui_story_30760401_1_35_dialog_content = "Mereka itu perangkat yang bisa melakukan segala macam tugas untukku, seperti pergi ke Generators untuk mengumpulkan energi.",
  ui_story_30760401_1_36_option_content = "Jadi, ruangan ini seharusnya bersih.",
  ui_story_30760401_1_37_dialog_content = "Lalu, kenapa berdebu di sini?",
  ui_story_30760401_1_38_dialog_content = "Pojok kecil ini... Mungkin belum dibersihkan.",
  ui_story_30760401_1_39_option_content = "Sepertinya... masih bisa lebih bersih.",
  ui_story_30760401_1_40_dialog_content = "Benar. Pojok-pojoknya berdebu.",
  ui_story_30760401_1_41_dialog_content = "PlayerName, tolong bersihkan sekarang. Tentu, aku akan bantu.",
  ui_story_30760401_1_42_dialog_content = "Tunggu? Kenapa?",
  ui_story_30760401_1_43_dialog_content = "Karena tentakelku benci debu, mereka sudah ingin... mengamuk.",
  ui_story_30760401_1_44_dialog_content = "Baiklah. Tolong... berhentilah mengancam seperti itu.",
  ui_story_30760401_1_45_dialog_content = "<color=#e8d9bb>Setelah sebuah sesi bersih-bersih dengan teliti...</color>",
  ui_story_30760401_1_46_dialog_content = "Waktu kau bilang akan bantu, kukira maksudmu bukan hanya berdiri di sana sambil memercikkan air dengan tentakelmu!",
  ui_story_30760401_1_47_dialog_content = "Kupikir kau sudah bekerja dengan baik, jadi aku tak mau mengganggumu.",
  ui_story_30760401_1_48_dialog_content = "Jadi, untuk prediksi ketiga, <color=#FFB400>ayo siapkan sesuatu untuk orang yang mungkin akan lewat sini</color>.",
  ui_story_30760401_1_49_dialog_content = "Orang lewat?",
  ui_story_30760401_1_50_dialog_content = "Ya. Tanpa tahu siapa yang akan lewat, masing-masing dari kita menaruh <color=#FFB400>hadiah</color> di meja ini.",
  ui_story_30760401_1_51_dialog_content = "Lalu kita minta orang yang lewat memilih mana yang ingin diambil.",
  ui_story_30760401_1_52_dialog_content = "Oke. Artinya, kita harus menebak siapa yang akan lewat?",
  ui_story_30760401_1_53_dialog_content = "Aku akan mulai... Pertama, beberapa kain beludru gelap yang mewah... Lalu lilin, mawar, dan anggur merah yang istimewa.",
  ui_story_30760401_1_54_dialog_content = "Tunggu! Dari mana kau dapat semua benda ini? Aku tidak ingat pernah melihatnya di Colossus.",
  ui_story_30760401_1_55_dialog_content = "Ada banyak tempat untuk menyimpan barang... Di topiku, jubahku, tentakelku...",
  ui_story_30760401_1_56_dialog_content = "Aku tak peduli dari mana kau dapat semua itu, tapi bukannya ini curang? Bukannya kau bilang satu hadiah?",
  ui_story_30760401_1_57_dialog_content = "Tenang, aku janji akan mengikuti aturan. Satu-satunya hadiah yang akan aku berikan adalah <color=#FFB400>anggur merah istimewa</color> ini.",
  ui_story_30760401_1_58_dialog_content = "Dalam hal nilai dan rasa, ini anggur terbaik. Disajikan hanya untuk para tamu yang paling terhormat.",
  ui_story_30760401_1_59_dialog_content = "Benda lainnya hanya di sini untuk memenuhi meja, membuat anggur ini tampak makin seperti hadiah—",
  ui_story_30760401_1_60_dialog_content = "<color=#FFB400>Harap ingat ini, ya.</color>",
  ui_story_30760401_1_61_dialog_content = "Jadi, apa yang kau siapkan?",
  ui_story_30760401_1_62_dialog_content = "(Hadiah...? Aku tidak punya satu pun benda berharga...)",
  ui_story_30760401_1_63_dialog_content = "(Satu-satunya keunggulanku sekarang adalah aku tahu ada lebih banyak perempuan di Colossus daripada laki-laki!)",
  ui_story_30760401_1_64_option_content = "Taruh sebuah pena di meja",
  ui_story_30760401_1_65_dialog_content = "<color=#e8d9bb>Setelah beberapa saat...</color>",
  ui_story_30760401_1_66_dialog_content = "Ha? Kalian ingin aku memilih salah satu dari dua hadiah ini? Betul bisa ambil satu...?",
  ui_story_30760401_1_67_dialog_content = "Aku tidak suka anggur, jadi yang ini saja.",
  ui_story_30760401_1_68_dialog_content = "(Seperti yang diperkirakan, Vice memilih hadiah yang aku siapkan!)",
  ui_story_30760401_1_69_dialog_content = "Sepertinya kau menang.",
  ui_story_30760401_1_70_option_content = "Taruh beberapa hidangan pencuci mulut di meja",
  ui_story_30760401_1_71_dialog_content = "<color=#e8d9bb>Setelah beberapa saat...</color>",
  ui_story_30760401_1_72_dialog_content = "Hadiah?",
  ui_story_30760401_1_73_dialog_content = "Hmm... Wah... Sepertinya yang ini saja...",
  ui_story_30760401_1_74_dialog_content = "Seorang gadis bersayap lewat. Walau ragu-ragu, dia akhirnya mengambil hidangan pencuci mulutmu.",
  ui_story_30760401_1_75_dialog_content = "Sepertinya kau menang.",
  ui_story_30760401_1_76_dialog_content = "Sekarang, untuk <color=#FFB400>prediksi terakhir</color>, yang kebetulan juga paling penting. Tolong dengarkan sungguh-sungguh—",
  ui_story_30760401_1_77_dialog_content = "<color=#FFB400>Siapa yang berikutnya akan memasuki ruangan ini?</color>",
  ui_story_30760401_1_78_dialog_content = "Lagi? Bagaimana bisa aku menebaknya? Bukannya itu terlalu sulit?",
  ui_story_30760401_1_79_dialog_content = "Yang sebelumnya tentang orang lewat, sekarang tentang orang masuk. Sebagai pemilik Colossus, kau harusnya tahu setiap orang di sini.",
  ui_story_30760401_1_80_dialog_content = "Sebenarnya, sejauh ini kau sudah cukup baik.",
  ui_story_30760401_1_81_dialog_content = "Hmm, coba kupikir dulu.",
  ui_story_30760401_1_82_dialog_content = "Tentu saja, kita berdua perlu waktu untuk memikirkan ini...",
  ui_story_30760401_1_83_dialog_content = "(Nah, menurut logika sekarang ini...)",
  ui_story_30760401_1_84_option_content = "Kupikir...",
  ui_story_30760401_1_85_dialog_content = "Ha? Di mana Kleken? Aku hanya menunduk sejenak dan sekarang dia hilang!",
  ui_story_30760401_1_86_dialog_content = "Apa dia keluar...? Apa mungkin dia mau curang?",
  ui_story_30760401_1_87_dialog_content = "Di sini rasanya cukup nyaman. Tadinya aku hanya berencana mampir sebentar... Aku tak menyangka kau akan <color=#FFB400>sangat pengertian</color>.",
  ui_story_30760401_1_88_dialog_content = "(Sh-Sh-Shadowlord...!?)",
  ui_story_30760401_1_89_dialog_content = "Suasananya tenang, dan aku bisa menikmati kesendirian. <color=#FFB400>Tidak ada orang yang berkerumun di depan pintuku</color>. Tempat yang bagus.",
  ui_story_30760401_1_90_dialog_content = "Aku, aku hanya...",
  ui_story_30760401_1_91_dialog_content = "Bahkan lantainya bersih sempurna. <color=#FFB400>Apa pojok-pojoknya juga sudah dibersihkan</color>?",
  ui_story_30760401_1_92_dialog_content = "(Apa ini artinya...)",
  ui_story_30760401_1_93_dialog_content = "<color=#FFB400>Taplak beludru, anggur merah...</color> Kau sudah mencari tahu benda-benda favoritku, ya?",
  ui_story_30760401_1_94_dialog_content = "Kau memang menarik, PlayerName...",
  ui_story_30760401_1_95_dialog_content = "(Apa Kleken diam-diam merencanakan ini!?)",
  ui_story_30760401_1_96_dialog_content = "(Memangnya tidak bisa langsung bilang bahwa Istvan akan datang!?)",
  ui_story_30760401_1_97_dialog_content = "Tentu saja, aku sengaja tidak mengatakannya secara langsung supaya semua jadi lebih menarik.",
  ui_story_30760401_1_98_dialog_content = "(Ah... Itukah yang dia maksud...?)",
  ui_story_30760401_1_99_dialog_content = "Bagus. Aku bisa melihat kesungguhanmu. Kalau begitu, aku yakin kau tidak akan mengecewakanku dalam percakapan yang akan kita lakukan sekarang.",
  ui_story_30760401_1_100_dialog_content = "Hah? Apa—!?",
  ui_story_30760301_1_1_dialog_content = "Apa yang harus kulakukan dengan <color=#FFB400>Dibury's Map</color> ini? Aku benar-benar tidak tahu.",
  ui_story_30760301_1_2_dialog_content = "Mudah sekali. Kau menarik kartu kelas setelah memilih satu.",
  ui_story_30760301_1_3_dialog_content = "Aku menarik kartu kelas Civilian.",
  ui_story_30760301_1_4_dialog_content = "Beruntung, aku dapat kartu Scam Artist.",
  ui_story_30760301_1_5_dialog_content = "Tunggu... Apa kartu kelas itu ada dalam permainan ini? Kau tidak curang, 'kan?",
  ui_story_30760301_1_6_dialog_content = "Tentu tidak. Lihat saja sendiri.",
  ui_story_30760301_1_7_dialog_content = "Hmm, <color=#FFB400>memang tertulis Scam Artist di kartu itu</color>...",
  ui_story_30760301_1_8_dialog_content = "Kita baru menghadapi bandit. Waktunya melempar dadu. Strategy dan Combat-mu harus lebih tinggi dari 6.",
  ui_story_30760301_1_9_dialog_content = "Strategy 8, Combat 9! Aku berhasil!",
  ui_story_30760301_1_10_dialog_content = "Strategy 13, Combat 4! Sepertinya aku harus menarik kartu Event.",
  ui_story_30760301_1_11_dialog_content = "Kartu Event ini bilang, \"Dokumen rahasiamu telah disita dan kau dijebloskan ke penjara bawah tanah.\"",
  ui_story_30760301_1_12_dialog_content = "Setiap melihat benda ini, aku selalu teringat <color=#FFB400>pengalamanku dulu</color>. Kau mau dengar?",
  ui_story_30760301_1_13_option_content = "Coba ceritakan.",
  ui_story_30760301_1_14_dialog_content = "Tampaknya kau bersemangat. Aku harus bercerita dengan lebih baik kalau begitu.",
  ui_story_30760301_1_15_option_content = "Tidak tertarik. Kenapa kau tiba-tiba bercerita?",
  ui_story_30760301_1_16_dialog_content = "Wah, kok begitu? Percayalah, ini cerita bagus. Sepertinya aku harus memaksamu mendengarkan.",
  ui_story_30760301_1_17_dialog_content = "<color=#e8d9bb>Di lubang bawah tanah yang terkubur puing-puing</color>",
  ui_story_30760301_1_18_dialog_content = "Kalau aku harus mati seperti ini, apa boleh buat. Hanya saja...",
  ui_story_30760301_1_19_dialog_content = "Ada orang di sana? Tolong, bantu kami!",
  ui_story_30760301_1_20_dialog_content = "Anak-anak, jangan berkumpul di sekitar kakiku.",
  ui_story_30760301_1_21_dialog_content = "Kami takut!!!",
  ui_story_30760301_1_22_dialog_content = "Jangan bergerak. Ada lubang di sini.",
  ui_story_30760301_1_24_dialog_content = "Apa kau Shadowlord?",
  ui_story_30760301_1_25_dialog_content = "Bukan. Kau bisa memanggilku Kleken, atau Swindler.",
  ui_story_30760301_1_26_dialog_content = "Kita harus bagaimana sekarang, Swindler?",
  ui_story_30760301_1_27_dialog_content = "Yah, kita bisa bermain sebentar. Aku punya sesuatu di sini—kebetulan aku membawa <color=#FFB400>Dibury's Map</color> ini. Lebih asyik daripada tidak melakukan apa-apa.",
  ui_story_30760301_1_28_dialog_content = "Wow, keren! Kenapa kau membawa permainan ini?",
  ui_story_30760301_1_29_dialog_content = "Aku membeli banyak hal dalam perjalanan kemari.",
  ui_story_30760301_1_30_dialog_content = "Tunggu sebentar!",
  ui_story_30760301_1_31_dialog_content = "Apa inti cerita acak ini?",
  ui_story_30760301_1_32_dialog_content = "Ini cerita tentang aku dan gadis-gadis kecil saat terkubur di bawah tanah.",
  ui_story_30760301_1_33_dialog_content = "Tidak, tidak, aku ingin tahu siapa gadis-gadis kecil ini, dan apa maksudnya mereka merayap di sekitar kakimu?",
  ui_story_30760301_1_34_dialog_content = "Kenapa mengeluarkan Dibury's Map? Dan apa maksudmu membeli banyak dalam perjalanan ke sana?",
  ui_story_30760301_1_35_dialog_content = "Hmm, akan kumulai dari awal...",
  ui_story_30760301_1_36_dialog_content = "<color=#e8d9bb>Sekitar satu tahun yang lalu...</color>",
  ui_story_30760301_1_37_dialog_content = "Kau pernah dengar <color=#FFB400>para bandit</color> di pinggiran Umbraton?",
  ui_story_30760301_1_38_dialog_content = "Aku tahu.",
  ui_story_30760301_1_39_dialog_content = "Mereka menculik dua gadis kecil yang terkait dengan organisasi kami dan memintaku bernegosiasi dengan mereka.",
  ui_story_30760301_1_40_dialog_content = "Tapi aku juga harus menghadiri pertemuan Guild hari itu, sesuatu yang mereka tahu dengan pasti.",
  ui_story_30760301_1_41_dialog_content = "Komplotan bandit itu tidak tahu wajahku, jadi aku ingin kau menggantikanku. Toh, kau sangat berpengalaman dalam menipu.",
  ui_story_30760301_1_42_dialog_content = "Kau mau aku berpura-pura jadi kau? Menarik. Baiklah.",
  ui_story_30760301_1_43_dialog_content = "Apakah itu kertas atau makanan, bawalah sebanyak yang kau perlu. Ada dendeng dan roti di meja. Ambil saja.",
  ui_story_30760301_1_44_dialog_content = "Kau pemimpin Istvan Gang?",
  ui_story_30760301_1_45_dialog_content = "Di mana para sandera? Aku ingin memastikan mereka aman.",
  ui_story_30760301_1_46_dialog_content = "Mereka aman di sana. Jangan khawatir, kami punya sesuatu untuk menghibur gadis-gadis itu.",
  ui_story_30760301_1_48_dialog_content = "Katakan apa yang kalian minta untuk melepaskan mereka. Keputusan ada padamu.",
  ui_story_30760301_1_49_dialog_content = "Cukup tanda tangani dokumen ini dan aku akan membiarkan mereka pergi.",
  ui_story_30760301_1_51_dialog_content = "\"Pengalihan Hak\"...",
  ui_story_30760301_1_52_dialog_content = "Bukan masalah. Selesai.",
  ui_story_30760301_1_53_dialog_content = "Kau terburu-buru sekali. Kau yakin sudah membacanya dengan benar?",
  ui_story_30760301_1_54_dialog_content = "Isinya, hak Istvan Gang untuk bekerja sama dengan Guild akan dialihkan kepadamu.",
  ui_story_30760301_1_55_dialog_content = "Kalian memilih melakukan penculikan hari ini untuk menyabotase pertemuan antara Istvan Gang dan Guilde, 'kan?",
  ui_story_30760301_1_56_dialog_content = "Benar. Senang rasanya bicara dengan orang yang cerdas. Kau jelas pantas menjadi pemimpin Istvan Gang.",
  ui_story_30760301_1_57_dialog_content = "Tunggu... Sejak kapan Shadowlord punya anak perempuan!?",
  ui_story_30760301_1_58_dialog_content = "Dia jelas tidak punya anak perempuan. Mungkin mereka mendapatkan informasi keliru sehingga salah paham.",
  ui_story_30760301_1_59_dialog_content = "Omong-omong, izinkan aku melanjutkan cerita...",
  ui_story_30760301_1_60_dialog_content = "Ya, semua sudah ditandatangani.",
  ui_story_30760301_1_61_dialog_content = "Sekarang setelah kau menandatanganinya seperti yang kami minta... Sandera ada di pondok itu. Silakan bawa mereka.",
  ui_story_30760301_1_62_dialog_content = "Jadi, bandit itu memperbolehkanmu mengambil para sandera dan pergi begitu saja?",
  ui_story_30760301_1_63_dialog_content = "Apa yang akan kau lakukan kalau berada di posisi mereka? Kau akan membiarkan kami pergi?",
  ui_story_30760301_1_64_option_content = "Ya, sesuai kesepakatan.",
  ui_story_30760301_1_65_dialog_content = "Toh, kau sudah menandatangani perjanjian itu, seperti yang mereka minta. Kalau aku tidak memperbolehkanmu pergi, kredibilitasku akan hancur.",
  ui_story_30760301_1_66_dialog_content = "Bandit seperti mereka tidak peduli dengan kredibilitas.",
  ui_story_30760301_1_67_option_content = "Tentu saja aku tidak akan membiarkan kau pergi.",
  ui_story_30760301_1_68_dialog_content = "Kalau kau membalas atau menyobek perjanjian itu setelahnya, penculikan itu akan sia-sia.",
  ui_story_30760301_1_69_dialog_content = "Kalau Shadowlord telah menandatangani perjanjian itu, Istvan Gang tidak akan mengingkari janji. Inilah yang disebut kredibilitas.",
  ui_story_30760301_1_70_dialog_content = "Jadi, kau benar-benar pergi ke pondok itu? Apa kau tidak takut mereka sudah memasang jebakan?",
  ui_story_30760301_1_71_dialog_content = "Kalau aku harus masuk, tentu saja. Keselamatan sandera adalah prioritasku.",
  ui_story_30760301_1_72_dialog_content = "Terus bagaimana?",
  ui_story_30760301_1_73_dialog_content = "Saat aku masuk untuk melepaskan ikatan mereka, dua gadis kecil itu sedang lelap. Lalu...",
  ui_story_30760301_1_74_dialog_content = "<size=50>Dhuar!</size>",
  ui_story_30760301_1_75_dialog_content = "Mereka meledakkan bom bawah tanah!",
  ui_story_30760301_1_76_dialog_content = "Bom? Ada yang terluka?",
  ui_story_30760301_1_77_dialog_content = "Jadi, di sinilah awal cerita kau dan gadis-gadis kecil itu terkubur di bawah puing-puing?",
  ui_story_30760301_1_78_dialog_content = "Ya. Walau itu bukan ledakan besar, aku masih harus mengeluarkan banyak sekali kekuatan untuk bertahan.",
  ui_story_30760301_1_79_dialog_content = "Kami tidak bisa langsung keluar karena aku perlu beberapa waktu untuk memulihkan diri.",
  ui_story_30760301_1_80_dialog_content = "Oke... Tapi kau bilang kau mengeluarkan Dibury's Map? Apa kalian benar-benar memainkannya?",
  ui_story_30760301_1_81_dialog_content = "Ya. Tapi tidak lama setelah kami mulai bermain, mereka malah menelan dadunya. Jadi, kami harus mengobrol saja di reruntuhan bawah tanah itu.",
  ui_story_30760301_1_82_dialog_content = "Kalian belum lama bergabung dengan Istvan Gang, kalau aku tak salah ingat.",
  ui_story_30760301_1_83_dialog_content = "Oh, kau mengenali kami. Kami <color=#FFB400>Patty</color> dan <color=#FFB400>Patsy</color>.",
  ui_story_30760301_1_84_dialog_content = "Bagaimana kalian bisa tertangkap? Mereka tampaknya tidak cukup kuat...",
  ui_story_30760301_1_85_dialog_content = "Kami sedang bermain, lalu pingsan karena lapar di tepi jalan. Saat membuka mata, tahu-tahu kami sudah diculik.",
  ui_story_30760301_1_86_dialog_content = "Pantas kalian selalu tidur di tanah. Shadowlord pasti menyiapkan makanan ini untuk kalian.",
  ui_story_30760301_1_87_dialog_content = "Dendeng!",
  ui_story_30760301_1_88_dialog_content = "Roti!",
  ui_story_30760301_1_89_dialog_content = "Nyam, nyam...",
  ui_story_30760301_1_90_dialog_content = "Kami kenyang!",
  ui_story_30760301_1_91_dialog_content = "Ayo kembali bekerja. Mundur sedikit... Aku harus membersihkan puing-puing di atas kita.",
  ui_story_30760301_1_92_dialog_content = "Tentakel yang besar dan kuat sekali! Dari mana datangnya mereka?",
  ui_story_30760301_1_93_dialog_content = "Jangan pikirkan. <color=#FFB400>Anggap saja ilusi</color>. Sekarang, giliranmu bekerja...",
  ui_story_30760301_1_94_dialog_content = "Mungkin hanya ada beberapa bandit yang menjaga markas. Aku tahu di mana mereka. Ayo gigit...",
  ui_story_30760301_1_95_dialog_content = "Setelah itu, kami merebut markas mereka dengan mudah. Akhir yang bahagia.",
  ui_story_30760301_1_96_dialog_content = "Tunggu... Ah, akhirnya kau membuatku mengatakannya!",
  ui_story_30760301_1_97_dialog_content = "Kenapa kau pikir hanya ada beberapa bandit yang menjaga markas?",
  ui_story_30760301_1_98_dialog_content = "Mudah saja, karena bos mereka pergi ke Guild dengan kacung-kacungnya dan perjanjian itu.",
  ui_story_30760301_1_99_dialog_content = "Perjanjian yang kau tanda tangani? Itu pasti tidak akan dianggap sah.",
  ui_story_30760301_1_100_dialog_content = "Tidak, aku menandatangani nama Istvan dan menggunakan capnya.",
  ui_story_30760301_1_101_dialog_content = "Dokumen itu sah, sayang sekali...",
  ui_story_30760301_1_102_dialog_content = "<color=#e8d9bb>Di pertemuan rahasia</color>",
  ui_story_30760301_1_103_dialog_content = "Siapa kau, dan apa yang kau lakukan di sini, orang asing?",
  ui_story_30760301_1_104_dialog_content = "Kau pemimpin Guild? Mulai hari ini, geng kami akan bekerja sama denganmu.",
  ui_story_30760301_1_105_dialog_content = "Ini dokumen \"Pengalihan Hak\", ditandatangani sendiri oleh Istvan.",
  ui_story_30760301_1_106_dialog_content = "Perjanjian? Bukankah itu <color=#FFB400>Dibury's Map</color>? Oh, itu dari kelompok produksi yang sama dengan yang baru saja kami luncurkan.",
  ui_story_30760301_1_107_dialog_content = "Namun, jelas tertulis di kertas ini bahwa... Tidak! <color=#FFB400>Ini pasti ilusi</color>!",
  ui_story_30760301_1_108_dialog_content = "Sial! Istvan menipu kita!? Bagaimana bisa!?",
  ui_story_30760301_1_109_dialog_content = "Istvan kebetulan ada di sini bersama sekelompok pembantunya. Kau mau bertemu dengannya?",
  ui_story_30760301_1_110_dialog_content = "Kau sudah jauh-jauh datang. Silakan duduk...",
  ui_story_30760301_1_111_dialog_content = "Maka, para bandit itu diarahkan langsung kepada Shadowlord. Sekali lagi, akhir yang bahagia.",
  ui_story_30760301_1_112_dialog_content = "Bandit-bandit itu mengambil Dibury's Map? Bagaimana bisa mereka mengira itu perjanjian kalian?",
  ui_story_30760301_1_113_dialog_content = "Mereka sudah mengeceknya berulang kali. Kalau kau, apa kau akan tertipu oleh tipu muslihatku?",
  ui_story_30760301_1_114_option_content = "Kalau kau yang melakukannya... Mungkin?",
  ui_story_30760301_1_115_dialog_content = "Sepertinya kau setidaknya sudah sedikit mengenalku.",
  ui_story_30760301_1_116_option_content = "Tidak mungkin! Aku pasti akan bisa mengetahuinya!",
  ui_story_30760301_1_117_dialog_content = "Punya rasa percaya diri seperti itu tidaklah buruk.",
  ui_story_30760301_1_118_dialog_content = "Kalau begitu, lihat ini.",
  ui_story_30760301_1_119_dialog_content = "Ha? Bukannya ini kartu kelas yang pertama kau tarik tadi?",
  ui_story_30760301_1_120_dialog_content = "Apa tulisannya?",
  ui_story_30760301_1_121_dialog_content = "Hmm... Kelas, <color=#FFB400>Gangster</color>? Kok bisa!?",
  ui_story_30760301_1_122_dialog_content = "Tadi tulisannya <color=#FFB400>Scam Artist</color>! Apa kau curang dan mengganti kartu?",
  ui_story_30760301_1_123_dialog_content = "Tidak, sejak awal tidak ada Scam Artist di dalam permainan Dibury's Map.",
  ui_story_30760301_1_124_dialog_content = "<color=#FFB400>Yang kau lihat tadi... Anggap saja ilusi.</color>",
  ui_story_30760601_1_1_dialog_content = "Matahari yang menyengat, pasir yang membakar...",
  ui_story_30760601_1_2_dialog_content = "Ada sesuatu yang terasa aneh... <color=#FFB400>Cita-cita itu</color>... sungguh mencurigakan...",
  ui_story_30760601_1_3_dialog_content = "Lalu kenapa aku... berlarian di hari yang begitu panas...",
  ui_story_30760601_1_4_dialog_content = "Dan mengantarkan kiriman ke tempat <color=#FFB400>Kleken</color>?!",
  ui_story_30760601_1_5_dialog_content = "Kleken!",
  ui_story_30760601_1_6_dialog_content = "Oh, kau kembali! Sudah kaukirimkan?",
  ui_story_30760601_1_7_dialog_content = "Ya, sudah... Kau...",
  ui_story_30760601_1_8_dialog_content = "Siapa kau?",
  ui_story_30760601_1_9_dialog_content = "Ah... Kasihan, kau ke sana kemari di pantai untuk mengantarkan kirimanku sepanjang hari.",
  ui_story_30760601_1_10_dialog_content = "Tampaknya pikiranmu kacau karena panasnya cuaca. Kau bahkan tidak ingat apa yang sangat kau cemaskan...",
  ui_story_30760601_1_11_dialog_content = "Siapa lagi yang akan ke sini, selain aku?",
  ui_story_30760601_1_12_dialog_content = "K-Kleken?! Apa kau memang tampak sangat muda seperti ini dari dulu?!",
  ui_story_30760601_1_13_dialog_content = "Selamat! Kau menemukan lagi sebuah fakta baru.",
  ui_story_30760601_1_14_dialog_content = "Saat cuaca sepanas ini, <color=#FFB400>aku menjadi Kleken yang sangat berbeda</color>.",
  ui_story_30760601_1_15_dialog_content = "Omong-omong, bagaimana kalau kau duduk dan beristirahat dulu? Mau minum?",
  ui_story_30760601_1_16_dialog_content = "Aku masih punya beberapa kiriman lagi yang perlu kau antarkan.",
  ui_story_30760601_1_17_dialog_content = "Tidak... Tidak! Aku tidak akan lagi membantumu mengirimkan apa pun! Lakukan saja sendiri!",
  ui_story_30760601_1_18_dialog_content = "Santai, PlayerName, tidak perlu membentakku seperti itu. Toh, kau 'kan yang berjanji untuk membantuku \"menyelesaikan urusanku yang belum selesai\".",
  ui_story_30760601_1_19_dialog_content = "Kalau kau lupa, aku tidak keberatan membantumu mengingat...",
  ui_story_30760601_1_20_dialog_content = "J-jangan mendekat! Aku bisa cari tahu sendiri bagaimana kau menipuku, terima kasih!",
  ui_story_30760601_1_21_dialog_content = "Pernah dengar kisah pahlawan yang pergi ke istana bawah air dan mengalahkan monster laut besar? Bagus sekali ceritanya.",
  ui_story_30760601_1_22_dialog_content = "Itulah kenapa kupikir kau harus mengawasi sebelah kirimu juga, pahlawan kecil...",
  ui_story_30760601_1_23_dialog_content = "Graagh!",
  ui_story_30760601_1_24_dialog_content = "Akhirnya aku... selesai...",
  ui_story_30760601_1_25_dialog_content = "Kenapa aku tahan dengan bahaya seperti ini selama ini?!",
  ui_story_30760601_1_26_dialog_content = "Untuk membantuku mendapatkan produk yang sangat penting ini, tentu saja.",
  ui_story_30760601_1_27_dialog_content = "Tidak, kukira kau cuma punya beberapa masalah kecil saat bersiap untuk Ocean Sovereign...",
  ui_story_30760601_1_28_dialog_content = "Jadi, kau memintaku membantu...",
  ui_story_30760601_1_29_dialog_content = "Siapa yang tahu ternyata kau memintaku mencari Eclipsite, lalu menyeretku untuk menghadapi gerombolan mereka?!",
  ui_story_30760601_1_30_dialog_content = "...",
  ui_story_30760601_1_31_dialog_content = "Hoi, kenapa diam? Ada penjelasan?",
  ui_story_30760601_1_32_dialog_content = "Maaf... Penjelasan apa yang kau mau? Aku akan meletakkan ini sejenak...",
  ui_story_30760601_1_33_dialog_content = "Kau... tidak apa-apa?",
  ui_story_30760601_1_34_dialog_content = "Aku tidak apa-apa. Hanya hampir jatuh saja.",
  ui_story_30760601_1_35_dialog_content = "(Bagaimana bisa seseorang setangkas Kleken \"hampir jatuh\"? Apa dia...)",
  ui_story_30760601_1_36_dialog_content = "Kau berkeringat?",
  ui_story_30760601_1_37_dialog_content = "Tentu saja... Cuaca panas sekali...",
  ui_story_30760601_1_38_dialog_content = "Tapi, kau masih mengenakan pakaian yang tebal seperti itu... Kau membakar semua energimu dengan melawan Eclipsite sambil memakai baju lengkap.",
  ui_story_30760601_1_39_dialog_content = "Tapi, yang lebih penting... Apa kau terluka dalam pertempuran tadi?",
  ui_story_30760601_1_40_dialog_content = "Eh... Sepertinya kau berhasil mengetahui rahasiaku. Lumayan, PlayerName.",
  ui_story_30760601_1_41_dialog_content = "Maaf... Aku sedang merasa tidak seperti biasanya...",
  ui_story_30760601_1_42_dialog_content = "Aku benar-benar minta maaf... Tapi, sepertinya aku tidak lagi merasa bisa menyelesaikan ini sendiri...",
  ui_story_30760601_1_43_dialog_content = "Sejujurnya, ini pertama kalinya aku melihatmu ambil risiko mengorbankan nyawamu seperti ini untuk sebuah pekerjaan...",
  ui_story_30760601_1_44_dialog_content = "Apa yang kau ambil dari para Eclipsite itu?",
  ui_story_30760601_1_45_dialog_content = "Bukalah dan kau akan tahu. Buka beberapa kotak ini dan lihatlah isinya.",
  ui_story_30760601_1_46_dialog_content = "Hmm...",
  ui_story_30760601_1_47_dialog_content = "Apa ini, sekotak penuh kain?",
  ui_story_30760601_1_48_dialog_content = "Sekotak penuh barang berharga.",
  ui_story_30760601_1_49_dialog_content = "\"Barang berharga\"? Maksudmu, kalian dulu dirampok oleh Eclipsite?",
  ui_story_30760601_1_50_dialog_content = "Ini bukan sekadar pekerjaan. Ini berkaitan dengan cita-citaku... dengan istana di hati kami.",
  ui_story_30760601_1_51_dialog_content = "Tapi, aku tidak lagi dapat mengirimkan barang ini kepada para pedagang Umbraton...",
  ui_story_30760601_1_52_dialog_content = "Dan mereka akan menderita karenanya, aku yakin.",
  ui_story_30760601_1_53_dialog_content = "Kalau berpikir seperti itu, hati nuraniku terasa memberontak.",
  ui_story_30760601_1_54_dialog_content = "Berhentilah bicara tentang cita-citamu!",
  ui_story_30760601_1_55_dialog_content = "Akan kubawa kotak-kotak ini! Ayo pergi sebelum Eclipsite menemukan kita!",
  ui_story_30760601_1_56_dialog_content = "Tidak... Kau pergilah dulu. Ada orang di sebelah selatan pantai, kirimkan ini kepadanya dalam setengah jam.",
  ui_story_30760601_1_57_dialog_content = "Seharusnya bukan masalah bagimu. Dengan kecepatanmu, kau pasti bisa melakukannya!",
  ui_story_30760601_1_58_dialog_content = "Ini, bawalah dan pergi. Teruslah berlari, dan jangan kembali.",
  ui_story_30760601_1_59_dialog_content = "Tolong... Pastikan barang ini sampai ke tangan orang itu.",
  ui_story_30760601_1_60_dialog_content = "Hah? Tapi, bagaimana denganmu?",
  ui_story_30760601_1_61_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_62_dialog_content = "Aku akan menahan mereka untukmu...",
  ui_story_30760601_1_63_dialog_content = "Kleken?!",
  ui_story_30760601_1_64_dialog_content = "Cepat, PlayerName! Lari!",
  ui_story_30760601_1_65_dialog_content = "Graagh!",
  ui_story_30760601_1_66_dialog_content = "Demikianlah, sang prajurit pemberani berlari, membawa harapan mereka ke tujuan akhir.",
  ui_story_30760601_1_67_dialog_content = "Dan saat dia menemui masalah, monster laut putih itu datang menyelamatkannya.",
  ui_story_30760601_1_68_dialog_content = "Ya... Terdengar seperti kisah yang indah. Mengenai judulnya...",
  ui_story_30760601_1_69_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_70_dialog_content = "Seberapa jauh lagi? Berapa lama lagi?",
  ui_story_30760601_1_71_dialog_content = "Dia mengorbankan diri tanpa ragu... Aku harus bisa mengantarkan barang ini kepada orang itu!",
  ui_story_30760601_1_72_dialog_content = "Aku pasti bisa... lalu aku mengajak yang lain kembali untuk menyelamatkannya!",
  ui_story_30760601_1_73_dialog_content = "*Terengah-engah* Huh... Akhirnya sampai juga...",
  ui_story_30760601_1_74_dialog_content = "Oh! Akhirnya kau sampai! Aku sudah menunggu sepanjang hari!",
  ui_story_30760601_1_75_dialog_content = "Barang ini sangat penting! Apa kau orang yang seharusnya menerimanya?",
  ui_story_30760601_1_76_dialog_content = "Tentu saja! Hmm, boleh juga... Sini, coba kulihat apa yang kita punya hari ini.",
  ui_story_30760601_1_77_dialog_content = "Tidak ada waktu! Kita harus kembali dan menyelamatkan Kleken! Dia dikepung Eclipsite!",
  ui_story_30760601_1_78_dialog_content = "Hah? Tapi, penjaga toko di sana baru mendapatkan pesan dari Kleken tidak sampai setengah jam lalu. Katanya...",
  ui_story_30760601_1_79_dialog_content = "Dia bilang semuanya sudah beres. Tinggal menunggu orang yang membawa barang tiba.",
  ui_story_30760601_1_80_dialog_content = "Eh? Setengah jam lalu?",
  ui_story_30760601_1_81_dialog_content = "Berarti tepat setelah aku pergi?",
  ui_story_30760601_1_82_dialog_content = "Selain itu, katanya dia menemukan orang yang sangat efisien untuk mengirimkan barang kali ini, jadi tidak perlu khawatir. Kau orang yang dia maksud, 'kan?",
  ui_story_30760601_1_83_dialog_content = "Tapi, kau sedikit lambat. Menurut hitungan kami, kau seharusnya tiba sepuluh menit lalu.",
  ui_story_30760601_1_84_dialog_content = "Dia telah meraup banyak untung dari pekerjaan ini. Bayaranmu dari dia pasti cukup besar, ya?",
  ui_story_30760601_1_85_dialog_content = "Kau bilang \"banyak untung\"? Bukannya Eclipsite itu merampok semua barang ini dari kalian?",
  ui_story_30760601_1_86_dialog_content = "Kau ini bicara apa? Kami baru mengimpor barang ini lewat Kleken, itu saja...",
  ui_story_30760601_1_87_dialog_content = "Aku... harus kembali dan meminta penjelasan tentang ini.",
  ui_story_30760601_1_88_dialog_content = "Kukira kau akan dimakan sekelompok Eclipsite!",
  ui_story_30760601_1_89_dialog_content = "Kukira kau memintaku pergi untuk melindungi sesuatu yang kau hargai lebih dari nyawamu sendiri!",
  ui_story_30760601_1_90_dialog_content = "Kukira kau lemah karena cuaca panas dan luka-lukamu!",
  ui_story_30760601_1_91_dialog_content = "Aku melawan matahari dan panas untuk mengirimkan barang itu, tapi pedagang itu bilang...",
  ui_story_30760601_1_92_dialog_content = "Bahwa itu sama sekali bukan barang mereka yang dirampok! Justru kau mencuri barang-barang seperti ini dari orang lain untuk dijual ke para pedagang?",
  ui_story_30760601_1_93_dialog_content = "Tenanglah, PlayerName. Ini semua cuma salah paham. Biar kujelaskan...",
  ui_story_30760601_1_94_dialog_content = "Saat aku datang ke sini, dan meminta bantuanmu...",
  ui_story_30760601_1_95_dialog_content = "Itu karena aku punya pekerjaan yang sangat penting, yaitu membasmi beberapa Eclipsite.",
  ui_story_30760601_1_96_dialog_content = "Kami, sebenarnya, mengalami masalah saat bersiap untuk Ocean Sovereign—segerombolan Eclipsite yang telah membuat markas di sini.",
  ui_story_30760601_1_97_dialog_content = "Selain itu, aku sungguh-sungguh terluka, dan tidak tahan dengan panas waktu itu.",
  ui_story_30760601_1_98_dialog_content = "Aku terlalu lemah untuk pekerjaan itu, dan kau membantuku melakukannya. Aku harus berterima kasih.",
  ui_story_30760601_1_99_dialog_content = "Tapi, ketika aku bertanya apakah itu barang milik kalian, kenapa kau...",
  ui_story_30760601_1_100_dialog_content = "Sudah kubilang, ini berkaitan dengan <color=#FFB400>cita-citaku</color>, dan <color=#FFB400>istana di hati kami</color>.",
  ui_story_30760601_1_101_dialog_content = "Kenapa kau sengaja menghindari pertanyaanku?!",
  ui_story_30760601_1_102_dialog_content = "Kupikir maksudmu barang itu penting untuk mewujudkan cita-citamu!",
  ui_story_30760601_1_103_dialog_content = "Aku bahkan mengira kalian mungkin berusaha menabung untuk membangun istana!",
  ui_story_30760601_1_104_dialog_content = "Hehe... Lumayan juga, PlayerName. Kau menguak fakta yang sebenarnya lebih cepat daripada perkiraanku.",
  ui_story_30760601_1_105_dialog_content = "Tapi, kalau kau kira aku melakukan ini hanya demi uang, kau salah besar.",
  ui_story_30760601_1_106_dialog_content = "Aku, sebenarnya, bertindak demi cita-citaku.",
  ui_story_30760601_1_107_dialog_content = "Apa artinya itu?! Karena aku, sebenarnya, yakin kau hanya memanfaatkanku demi uang!",
  ui_story_30760601_1_108_dialog_content = "Kau memanfaatkanku untuk menemukan Eclipsite, dan kau memanfaatkanku untuk mengirimkan barang itu...",
  ui_story_30760601_1_X108_dialog_content = "Tapi, yang paling penting, tidak satu pun barang itu yang merupakan milik kalian.",
  ui_story_30760601_1_X109_dialog_content = "Pernahkah kau memikirkan secemas apa pemilik asli barang-barang itu sekarang?",
  ui_story_30760601_1_X110_dialog_content = "Apa menurutmu kau bisa menjual apa pun yang kau curi dari Eclipsite?",
  ui_story_30760601_1_109_dialog_content = "Cukup. Menurut investigasi Istvan Gang atas barang-barang itu, kami menyimpulkan...",
  ui_story_30760601_1_110_dialog_content = "Bahwa barang-barang itu <color=#FFB400>tidak punya pemilik</color>.",
  ui_story_30760601_1_111_dialog_content = "Terus kenapa? Kau mau bilang bahwa ini bukan pekerjaan kotor, begitu?",
  ui_story_30760601_1_112_dialog_content = "Benar. Ini adalah sebuah informasi yang sangat penting. Tanpanya, kau pasti akan salah memahami maksudku.",
  ui_story_30760601_1_113_dialog_content = "Uang yang kudapat hanyalah untuk membasmi Eclipsite saja, tidak ada yang lain.",
  ui_story_30760601_1_114_dialog_content = "Sisanya langsung kubayarkan kepada Istvan Gang.",
  ui_story_30760601_1_115_dialog_content = "Kau mungkin tidak tahu, tapi Shadowlord sangat suka melakukan \"kebaikan\".",
  ui_story_30760601_1_116_dialog_content = "Baiklah...",
  ui_story_30760601_1_117_dialog_content = "Maaf, kuakui aku sedikit salah memahamimu tadi.",
  ui_story_30760601_1_118_dialog_content = "Bukan masalah.",
  ui_story_30760601_1_119_dialog_content = "Sebagai Scam Artist, aku lebih suka disalahpahami daripada dipercayai.",
  ui_story_30760601_1_120_dialog_content = "Kenapa aku merasa kata-katamu itu sarkasme...",
  ui_story_30760601_1_121_dialog_content = "Jadi, apa \"cita-cita\" yang dari tadi kau bicarakan? Kau bilang kau bertindak demi cita-citamu, 'kan?",
  ui_story_30760601_1_122_dialog_content = "Setelah mendengar kau menjual barang tadi ke pedagang itu, kupikir kau melakukannya demi uang...",
  ui_story_30760601_1_123_dialog_content = "Tapi, menggunakan uang kotor... untuk membangun istana? Yah, setidaknya sekarang aku tahu uang itu tidak kotor.",
  ui_story_30760601_1_124_dialog_content = "Festival itu.",
  ui_story_30760601_1_125_dialog_content = "Bagaimanapun, Ocean Sovereign tetap sebuah festival.",
  ui_story_30760601_1_126_dialog_content = "Oh... Aku jelas tahu bahwa itu festival. Jawaban macam apa itu?",
  ui_story_30760601_1_127_dialog_content = "Sabar dulu. Cita-cita haruslah dijelaskan dengan detail yang sempurna agar bisa menarik hati orang lain.",
  ui_story_30760601_1_128_dialog_content = "Dahulu kala, hiduplah seorang pahlawan...",
  ui_story_30760601_1_129_dialog_content = "Dia mengarungi laut dalam dengan kapal kerajaan, mencari harta karun yang legendaris...",
  ui_story_30760601_1_130_dialog_content = "Suatu hari, dia bertemu dengan seekor monster laut putih raksasa.",
  ui_story_30760601_1_131_dialog_content = "Dan bersama monster itu, dia menemukan istana bawah air yang luar biasa.",
  ui_story_30760601_1_132_dialog_content = "Setelah akhirnya menemukan harta karun, dia membuat perjanjian dengan monster itu untuk membasmi monster-monster lain yang berbahaya dan mengganggu lautan.",
  ui_story_30760601_1_133_dialog_content = "Ini salah satu cerita favoritku. Judulnya <color=#FFB400>\"An Adventurer's Voyage\".</color>",
  ui_story_30760601_1_134_dialog_content = "Istana dari sebuah cerita? Tapi, bukankah \"An Adventurer's Voyage\" itu hanya sekadar dongeng?",
  ui_story_30760601_1_135_dialog_content = "Atau maksudmu, itu ada kaitannya dengan Ocean Sovereign?",
  ui_story_30760601_1_136_dialog_content = "Alasan aku datang ke sini adalah mencari tahu hubungan di antara keduanya.",
  ui_story_30760601_1_137_dialog_content = "Untuk melihat istana dari cerita itu.",
  ui_story_30760601_1_138_dialog_content = "Selama aku memohon dengan tulus kepada Neptunus, dia akan mengabulkan keinginanku dan istana itu akan muncul di hadapanku.",
  ui_story_30760601_1_139_dialog_content = "Membantu orang mengadakan Ocean Sovereign dengan lancar adalah salah satu caraku menunjukkan ketulusan.",
  ui_story_30760601_1_140_dialog_content = "Terdengar mencurigakan...",
  ui_story_30760601_1_141_dialog_content = "Kau pikir cerita itu berdasarkan kisah nyata? Atau menurutmu istana bawah air itu tidak ada?",
  ui_story_30760601_1_142_option_content = "Aku tidak pernah membaca cerita itu.",
  ui_story_30760601_1_143_dialog_content = "...",
  ui_story_30760601_1_144_dialog_content = "...",
  ui_story_30760601_1_145_dialog_content = "Aneh sekali. Tiba-tiba aku tidak tahu harus bagaimana untuk melanjutkan topik ini.",
  ui_story_30760601_1_146_dialog_content = "Tapi, tidak apa-apa. Bukan masalah kalau kau belum membaca cerita itu.",
  ui_story_30760601_1_147_option_content = "Aku percaya.",
  ui_story_30760601_1_148_dialog_content = "Mungkin istana di cerita itu nyata.",
  ui_story_30760601_1_149_dialog_content = "Aku senang kau bisa menjawab dan cepat percaya.",
  ui_story_30760601_1_150_dialog_content = "Aku hanya berharap hadiah yang sudah kusiapkan tidak membuatmu kecewa.",
  ui_story_30760601_1_151_dialog_content = "Hadiah?",
  ui_story_30760601_1_152_dialog_content = "Benar. Tidak setiap hari aku bertemu seseorang yang sangat tertarik dengan cita-citaku.",
  ui_story_30760601_1_153_dialog_content = "Sudah sepantasnya aku berterima kasih.",
  ui_story_30760601_1_154_option_content = "Aku tidak percaya sama sekali.",
  ui_story_30760601_1_155_dialog_content = "Cerita itu cuma karangan, 'kan?",
  ui_story_30760601_1_156_dialog_content = "Saat menulis cerita seperti ini, orang sering tidak sengaja merujuk kepada kejadian nyata.",
  ui_story_30760601_1_157_dialog_content = "Cerita itu sendiri mungkin karangan, tapi bisa saja pengarangnya membuat dongeng itu berdasarkan beberapa kisah nyata.",
  ui_story_30760601_1_158_dialog_content = "Itu salah satu cita-citaku. Terkadang terasa jauh dariku, terkadang sangat dekat.",
  ui_story_30760601_1_159_dialog_content = "Dalam legenda Ocean Sovereign, disebutkan sebuah istana.",
  ui_story_30760601_1_160_dialog_content = "Ada istana di legenda itu, dan ada istana di cerita tadi... Mungkin ada keterkaitan di antara keduanya.",
  ui_story_30760601_1_161_dialog_content = "Bagaimanapun, aku ingin kau juga melihatnya sendiri. Itulah alasanku meminta bantuanmu.",
  ui_story_30760601_1_162_dialog_content = "Walau tampak waktunya tidak tepat... Ah, mungkin aku bisa berusaha sedikit lebih keras.",
  ui_story_30760601_1_163_dialog_content = "Istana di dasar laut...",
  ui_story_30760601_1_164_dialog_content = "Bahkan jika yang tersisa hanya reruntuhan, itu masih pemandangan yang luar biasa...",
  ui_story_30760601_1_165_dialog_content = "Sebuah bukti peradaban besar dan mengagumkan yang pernah ada di sini.",
  ui_story_30760601_1_166_dialog_content = "Istana? Kau... Kau benar-benar memanggil istana bawah laut itu?",
  ui_story_30760601_1_167_dialog_content = "Bagaimana menurutmu? Kau percaya istana itu ada sekarang?",
  ui_story_30760601_1_168_dialog_content = "Ya, aku...",
  ui_story_30760601_1_169_dialog_content = "Omong-omong, ini hanya ilusi. Kalau melihat lebih dekat, kau akan melihat trikku.",
  ui_story_30760601_1_170_dialog_content = "Aku tadi hampir berkata bahwa aku sekarang percaya... Tapi, kau memotongku.",
  ui_story_30760601_1_171_dialog_content = "Eh... Jangan marah. Membuat ilusi hanyalah salah satu dari kekuatanku.",
  ui_story_30760601_1_172_dialog_content = "Sayangnya, aku tidak bisa menahannya lagi. Aku masih sangat lemah sekarang.",
  ui_story_30760601_1_173_dialog_content = "Tunggu sebentar, kau beristirahat cukup nyaman saat aku kembali...",
  ui_story_30760601_1_174_dialog_content = "Kau bahkan berganti pakaian dengan baju renang yang entah dari mana asalnya...",
  ui_story_30760601_1_175_dialog_content = "Dan kau masih bisa menggunakan kekuatanmu seperti ini?",
  ui_story_30760601_1_176_dialog_content = "Selain itu, orang-orang lain bilang pekerjaan hari ini mudah, menurutmu...",
  ui_story_30760601_1_177_dialog_content = "Apa kau memang selemah itu sekarang?",
  ui_story_30760601_1_178_dialog_content = "Hmm... Tampaknya kau memang suka menganalisis segala sesuatu dengan berlebihan...",
  ui_story_30760601_1_179_dialog_content = "Eh... Bukankah kau bisa berdiri normal barusan?",
  ui_story_30760601_1_180_dialog_content = "Tunggu, sial... Kenapa aku merasa kau akan mengelabuiku lagi?",
  ui_story_30760601_1_181_dialog_content = "Hmm, walau kekuatanku hampir habis, kurasa aku masih bisa melakukannya.",
  ui_story_30760601_1_182_dialog_content = "Setidaknya, aku ingin menunjukkan kepadamu istana yang kuimpikan.",
  ui_story_30760601_1_183_dialog_content = "Baiklah, baiklah, maaf sudah salah memahamimu lagi... Kupikir kau masih memiliki sedikit kekuatan, tapi rupanya tidak.",
  ui_story_30760601_1_184_dialog_content = "Aku tidak pernah mengira kau mau berusaha sekeras itu...",
  ui_story_30760601_1_185_dialog_content = "Anggap saja ini imbalanmu.",
  ui_story_30760601_1_186_dialog_content = "Eh?",
  ui_story_30760601_1_187_dialog_content = "Sederhana dan terkadang gegabah, tapi dengan kepekaan yang hampir tidak normal.",
  ui_story_30760601_1_188_dialog_content = "Kau punya aura pahlawan.",
  ui_story_30760601_1_189_dialog_content = "Dan pahlawan adalah sesuatu yang diperlukan cerita ini agar lengkap.",
  ui_story_30760601_1_190_dialog_content = "Sebagai imbalan karena sudah membantuku mengantar barang itu, aku memutuskan untuk membuatmu melihat pemandangan yang spektakuler ini.",
  ui_story_30760601_1_191_dialog_content = "Dengan cara ini, aku juga tidak perlu membayarmu dengan uang tunai.",
  ui_story_30760601_1_192_dialog_content = "...",
  ui_story_30760601_1_193_dialog_content = "Yang terakhir itu sungguh tidak perlu kau katakan, Kleken...",
  ui_story_30760601_1_194_dialog_content = "Betulkah? Tapi, kupikir selama mendapatkan imbalan, kau akan mau membantuku merampungkan usahaku?",
  ui_story_30760601_1_195_dialog_content = "Jadi, kau benar-benar ingin terus menyuruh-nyuruh aku?! Apa kau tidak bisa membiarkan momen tadi berlanjut sedikit lebih lama?!",
  ui_story_30760601_1_196_dialog_content = "Tentu saja tidak.",
  ui_story_30760601_1_197_dialog_content = "\"Pengiriman Heroik\"... Pasti jadi cerita yang cukup menarik, 'kan?",
  ui_story_30760601_1_198_dialog_content = "Itu bukan cerita sungguhan!!",
  ui_story_30760601_1_199_dialog_content = "Sebenarnya itu baru saja terpikirkan olehku. Semoga kau suka!"
}
return config
